import { describe, expect, it } from 'vitest';
import { createGrid, withLetter, type Coord, type Grid } from '../engine/grid';
import { buildWord } from './build-word';

// Story 21-S1 — the word highlight. A word in the build phase is the
// unbroken run of lettered cells through a cell, in a direction, ended by
// an empty cell or the grid's edge. A run of 2 or more letters is a word;
// an empty cell or a lone letter has none (null).
//
// Do not edit this file to match an implementation.

/** A grid from rows of text: a letter is a lettered cell, '.' an empty one. */
function gridOf(rows: string[]): Grid {
  let grid = createGrid({ cols: rows[0].length, rows: rows.length });
  rows.forEach((letters, row) => {
    [...letters].forEach((letter, col) => {
      if (letter !== '.') grid = withLetter(grid, { col, row }, letter);
    });
  });
  return grid;
}

const across = (row: number, cols: number[]): Coord[] => cols.map((col) => ({ col, row }));
const down = (col: number, rows: number[]): Coord[] => rows.map((row) => ({ col, row }));

describe('21-S1-1 the run', () => {
  //   . C A T . .     row 0: CAT, ended by empty cells on both sides
  //   D . . . . O     column 0: DOG; column 5: OX, both between empties
  //   O . . . . X
  //   G . H I . .     row 3: HI, two letters
  //   . . . . . .
  //   S T R A N D     row 5: edge to edge
  const grid = gridOf(['.CAT..', 'D....O', 'O....X', 'G.HI..', '......', 'STRAND']);

  it('across, ended by empty cells, from any of its cells', () => {
    for (const col of [1, 2, 3]) {
      expect(buildWord(grid, { col, row: 0 }, 'across')).toEqual(across(0, [1, 2, 3]));
    }
  });

  it('down, ended by empty cells, from any of its cells', () => {
    for (const row of [1, 2, 3]) {
      expect(buildWord(grid, { col: 0, row }, 'down')).toEqual(down(0, [1, 2, 3]));
    }
    expect(buildWord(grid, { col: 5, row: 2 }, 'down')).toEqual(down(5, [1, 2]));
  });

  it('ended by one edge and an empty cell', () => {
    expect(buildWord(gridOf(['AB.']), { col: 1, row: 0 }, 'across')).toEqual(across(0, [0, 1]));
    expect(buildWord(gridOf(['.AB']), { col: 1, row: 0 }, 'across')).toEqual(across(0, [1, 2]));
    expect(buildWord(gridOf(['A', 'B', '.']), { col: 0, row: 0 }, 'down')).toEqual(down(0, [0, 1]));
    expect(buildWord(gridOf(['.', 'A', 'B']), { col: 0, row: 2 }, 'down')).toEqual(down(0, [1, 2]));
  });

  it('a run touching both edges', () => {
    expect(buildWord(grid, { col: 3, row: 5 }, 'across')).toEqual(across(5, [0, 1, 2, 3, 4, 5]));
    expect(buildWord(gridOf(['A', 'B', 'C']), { col: 0, row: 1 }, 'down')).toEqual(down(0, [0, 1, 2]));
  });

  it('a run of 2 letters is a word', () => {
    expect(buildWord(grid, { col: 2, row: 3 }, 'across')).toEqual(across(3, [2, 3]));
    expect(buildWord(grid, { col: 3, row: 3 }, 'across')).toEqual(across(3, [2, 3]));
  });

  it('a lone letter has no word in that direction', () => {
    // D at (0,1) is alone across; C at (1,0) is alone down.
    expect(buildWord(grid, { col: 0, row: 1 }, 'across')).toBeNull();
    expect(buildWord(grid, { col: 1, row: 0 }, 'down')).toBeNull();
    expect(buildWord(grid, { col: 5, row: 5 }, 'down')).toBeNull();
  });

  it('an empty cell has no word, even between lettered cells', () => {
    expect(buildWord(grid, { col: 0, row: 0 }, 'across')).toBeNull();
    expect(buildWord(grid, { col: 0, row: 4 }, 'down')).toBeNull();
    expect(buildWord(gridOf(['AB.CD']), { col: 2, row: 0 }, 'across')).toBeNull();
  });

  it('an empty grid has no word', () => {
    const empty = createGrid({ cols: 5, rows: 5 });
    expect(buildWord(empty, { col: 2, row: 2 }, 'across')).toBeNull();
    expect(buildWord(empty, { col: 2, row: 2 }, 'down')).toBeNull();
  });
});
